return $input.all().map((item, i) => {
  const conversation = item.json;
  const contact = conversation.contactDisplayName ?? conversation.externalUserId ?? 'No contact';
  const message = (conversation.lastMessageText ?? '').slice(0, 80);
  const reason = conversation.closeReason ? ' (' + conversation.closeReason + ')' : '';
  const line = (i + 1) + '. [' + conversation.origin + '] ' + contact + ' · agent ' + conversation.agentKey + ' · ' + conversation.status + reason + ' · ' + (conversation.messageCount ?? 0) + ' messages — "' + message + '"';
  return { json: { line } };
});
